function pad2(x){ return (x<10?'0':'')+x; }
function fmtDate(d){ return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate()); }
function dateAdd(dateStr, opts){
  opts=opts||{}; var n=Number(opts.n)||0; var unit=opts.unit||'day';
  var d = dateStr ? new Date(dateStr) : new Date();
  if(isNaN(d.getTime())) return {ok:false, reason:'invalid date'};
  var out=new Date(d.getTime());
  if(unit==='day') out.setDate(out.getDate()+n);
  else if(unit==='week') out.setDate(out.getDate()+n*7);
  else if(unit==='month'){
    var day=out.getDate();
    out.setDate(1);
    out.setMonth(out.getMonth()+n);
    var last=new Date(out.getFullYear(), out.getMonth()+1, 0).getDate();
    out.setDate(Math.min(day,last));
  }
  else if(unit==='year') out.setFullYear(out.getFullYear()+n);
  else return {ok:false, reason:'unknown unit'};
  return {ok:true, value:fmtDate(out)};
}

var EXPORTS={dateAdd:dateAdd,fmtDate:fmtDate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DateAddForgePure = EXPORTS; }
